using System.ComponentModel.DataAnnotations;
namespace RaceDay.Api.Models;
public class UserRole { public int RoleId {get;set;} public string RoleName {get;set;}=""; }
public class Organizer { public int OrganiserId {get;set;} public int RoleId {get;set;} public UserRole? Role {get;set;} public string FirstName {get;set;}=""; public string LastName {get;set;}=""; public string Email {get;set;}=""; public string PasswordHash {get;set;}=""; public string? PhoneNumber {get;set;} public DateTime CreatedAt {get;set;}=DateTime.UtcNow; public List<RaceEvent> Events {get;set;}=[]; }
public class Participant { public int ParticipantId {get;set;} public int RoleId {get;set;} public UserRole? Role {get;set;} public string FirstName {get;set;}=""; public string LastName {get;set;}=""; public string Email {get;set;}=""; public string PasswordHash {get;set;}=""; public string? PhoneNumber {get;set;} public DateOnly DateOfBirth {get;set;} public DateTime CreatedAt {get;set;}=DateTime.UtcNow; public List<Enrolment> Enrolments {get;set;}=[]; }
