public class RaceResult { public int ResultId {get;set;} public int EnrolmentId {get;set;} public Enrolment? Enrolment {get;set;} public TimeOnly? FinishTime {get;set;} public int? Position {get;set;} public string Status {get;set;}="Finished"; public DateTime RecordedAt {get;set;}=DateTime.UtcNow; }
